  truth_value_id                      TEXT                 PRIMARY KEY          -- Stored identity of the truth value: 'true', 'false', or 'null'.
);
ALTER TABLE truth_values ADD COLUMN IF NOT EXISTS symbol TEXT;                                      -- Single-letter symbol: T, F, or N.
ALTER TABLE truth_values ADD COLUMN IF NOT EXISTS glyph TEXT;                                       -- Logical glyph for the value.
ALTER TABLE truth_values ADD COLUMN IF NOT EXISTS rank INTEGER;                                     -- Strong Kleene order used by min/max: True=1, NULL=0, False=-1.
ALTER TABLE truth_values ADD COLUMN IF NOT EXISTS facts_with_value TEXT;                            -- Membership facts that resolve to this truth value.
COMMENT ON TABLE truth_values IS 'The three truth values a membership question or condition can take: True, False, or NULL. Admitting NULL makes membership a partial, non-bivalent semantics rather than the classical two-valued one; bivalence is recovered wherever a definition is grounded.';
COMMENT ON COLUMN truth_values.truth_value_id IS 'Stored identity of the truth value: ''true'', ''false'', or ''null''.';
COMMENT ON COLUMN truth_values.symbol IS 'Single-letter symbol: T, F, or N.';
COMMENT ON COLUMN truth_values.glyph IS 'Logical glyph for the value.';
COMMENT ON COLUMN truth_values.rank IS 'Strong Kleene order used by min/max: True=1, NULL=0, False=-1.';
COMMENT ON COLUMN truth_values.facts_with_value IS 'Membership facts that resolve to this truth value.';

