CREATE OR REPLACE FUNCTION get_sets_label(p_set_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT label FROM sets WHERE set_id = p_set_id);
$$ LANGUAGE sql STABLE;

-- get_sets_condition_expression
-- Helper function: Get ConditionExpression from Sets by SetId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_sets_condition_expression(p_set_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT condition_expression FROM sets WHERE set_id = p_set_id);
$$ LANGUAGE sql STABLE;

-- get_sets_is_self_referential
-- Helper function: Get IsSelfReferential from Sets by SetId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_sets_is_self_referential(p_set_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (SELECT is_self_referential FROM sets WHERE set_id = p_set_id);
$$ LANGUAGE sql STABLE;

-- get_evaluation_steps_step_order
-- Helper function: Get StepOrder from EvaluationSteps by EvaluationStepId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_evaluation_steps_step_order(p_evaluation_step_id TEXT)
RETURNS INTEGER AS $$
  SELECT (SELECT step_order FROM evaluation_steps WHERE evaluation_step_id = p_evaluation_step_id);
$$ LANGUAGE sql STABLE;

-- calc_membership_facts_name
-- Field: MembershipFacts.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_membership_facts_name(p_membership_fact_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(element, '') FROM membership_facts WHERE membership_fact_id = p_membership_fact_id), ' ∈ ', (SELECT NULLIF(container, '') FROM membership_facts WHERE membership_fact_id = p_membership_fact_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_membership_facts_is_null
-- Field: MembershipFacts.IsNull
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_membership_facts_is_null(p_membership_fact_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (SELECT NULLIF(membership_value, '') FROM membership_facts WHERE membership_fact_id = p_membership_fact_id) = 'null' THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_membership_facts_is_grounded
-- Field: MembershipFacts.IsGrounded
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_membership_facts_is_grounded(p_membership_fact_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (SELECT NULLIF(membership_value, '') FROM membership_facts WHERE membership_fact_id = p_membership_fact_id) = 'null' THEN FALSE ELSE TRUE END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_membership_facts_count_of_evaluation_steps
-- Field: MembershipFacts.CountOfEvaluationSteps
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_membership_facts_count_of_evaluation_steps(p_membership_fact_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM evaluation_steps WHERE membership_fact = (SELECT NULLIF(membership_fact_id, '') FROM membership_facts WHERE membership_fact_id = p_membership_fact_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_evaluation_steps_name
-- Field: EvaluationSteps.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_evaluation_steps_name(p_evaluation_step_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT('try ', (SELECT NULLIF(trial_value, '') FROM evaluation_steps WHERE evaluation_step_id = p_evaluation_step_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_evaluation_steps_is_stable
-- Field: EvaluationSteps.IsStable
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_evaluation_steps_is_stable(p_evaluation_step_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (SELECT NULLIF(trial_value, '') FROM evaluation_steps WHERE evaluation_step_id = p_evaluation_step_id) = (SELECT NULLIF(resulting_value, '') FROM evaluation_steps WHERE evaluation_step_id = p_evaluation_step_id) THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_evaluation_steps_outcome
-- Field: EvaluationSteps.Outcome
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_evaluation_steps_outcome(p_evaluation_step_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (SELECT NULLIF(trial_value, '') FROM evaluation_steps WHERE evaluation_step_id = p_evaluation_step_id) = (SELECT NULLIF(resulting_value, '') FROM evaluation_steps WHERE evaluation_step_id = p_evaluation_step_id) THEN ('stable fixed point')::text ELSE ('contradiction')::text END)::text;
$$ LANGUAGE sql STABLE;

