-- ----------------------------------------------------------------------------
-- Drop pass: every rulebook-owned view, reverse iteration order, CASCADE.
-- The rulebook is HEAD — the surviving view set must mirror it exactly.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_evaluation_steps CASCADE;
DROP VIEW IF EXISTS vw_membership_facts CASCADE;
DROP VIEW IF EXISTS vw_sets CASCADE;
DROP VIEW IF EXISTS vw_set_rules CASCADE;
DROP VIEW IF EXISTS vw_truth_table_rows CASCADE;
DROP VIEW IF EXISTS vw_connectives CASCADE;
DROP VIEW IF EXISTS vw_truth_values CASCADE;

-- ----------------------------------------------------------------------------
-- vw_truth_values: The three truth values a membership question or condition can take: True, False, or NULL. Admitting NULL makes membership a partial, non-bivalent semantics rather than the classical two-valued one; bivalence is recovered wherever a definition is grounded.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_truth_values CASCADE;
CREATE VIEW vw_truth_values WITH (security_invoker = ON) AS
SELECT
  t.truth_value_id,                                                             -- Stored identity of the truth value: 'true', 'false', or 'null'.
  calc_truth_values_name(t.truth_value_id) AS name,                             -- Display alias for the truth value.
  t.symbol,                                                                     -- Single-letter symbol: T, F, or N.
  t.glyph,                                                                      -- Logical glyph for the value.
  t.rank,                                                                       -- Strong Kleene order used by min/max: True=1, NULL=0, False=-1.
  calc_truth_values_is_classical(t.truth_value_id) AS is_classical,             -- True for the two bivalent values (True/False); False for NULL.
  calc_truth_values_is_undefined(t.truth_value_id) AS is_undefined,             -- True only for NULL, the undefined value meaning 'does not converge'.
  calc_truth_values_count_of_facts(t.truth_value_id) AS count_of_facts,         -- How many membership facts resolve to this value.
  t.facts_with_value                                                            -- Membership facts that resolve to this truth value.
FROM truth_values t;

-- ----------------------------------------------------------------------------
-- vw_connectives: Logical connectives whose Strong Kleene (K3) truth tables define how NULL propagates. This is the 'gap' route (NULL where evaluation fails to converge), the sibling of paraconsistent 'glut' logics, and it follows Kripke's fixed-point grounding.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_connectives CASCADE;
CREATE VIEW vw_connectives WITH (security_invoker = ON) AS
SELECT
  t.connective_id,                                                              -- Stored identity: 'negation', 'conjunction', or 'disjunction'.
  calc_connectives_name(t.connective_id) AS name,                               -- Display alias.
  t.symbol,                                                                     -- Operator glyph (not / and / or).
  t.arity,                                                                      -- Number of inputs: 1 for negation, 2 for conjunction/disjunction.
  t.kleene_rule,                                                                -- How the K3 output is computed (negate / min / max over ranks).
  calc_connectives_count_of_truth_table_rows(t.connective_id) AS count_of_truth_table_rows,-- Rows in this connective's truth table.
  t.truth_table_rows                                                            -- The truth-table rows belonging to this connective.
FROM connectives t;

-- ----------------------------------------------------------------------------
-- vw_truth_table_rows: One row per input combination per connective: the Strong Kleene semantics, stored as data.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_truth_table_rows CASCADE;
CREATE VIEW vw_truth_table_rows WITH (security_invoker = ON) AS
SELECT
  t.truth_table_row_id,                                                         -- Stored identity, e.g. 'negation|null|_|null'.
  t.connective,                                                                 -- The connective this row defines.
  t.left_input,                                                                 -- Left/sole input truth value.
  t.right_input,                                                                -- Right input truth value; null for the unary negation.
  t.output,                                                                     -- Resulting truth value for this input combination.
  calc_truth_table_rows_output_symbol(t.truth_table_row_id) AS output_symbol,   -- Symbol of the output value.
  calc_truth_table_rows_name(t.truth_table_row_id) AS name                      -- Readable row, e.g. 'negation: null -> null'.
FROM truth_table_rows t;

-- ----------------------------------------------------------------------------
-- vw_set_rules: The twelve structural rules of the theory: the eleven classical naive rules plus the missing Rule 12.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_set_rules CASCADE;
CREATE VIEW vw_set_rules WITH (security_invoker = ON) AS
SELECT
  t.set_rule_id,                                                                -- Stored identity, e.g. 'rule-12'.
  t.rule_number,                                                                -- Ordinal 1-12.
  t.title,                                                                      -- Short rule title.
  t.statement,                                                                  -- Full statement of the rule.
  calc_set_rules_name(t.set_rule_id) AS name,                                   -- Display alias 'R<n>'.
  calc_set_rules_is_classical(t.set_rule_id) AS is_classical,                   -- True for the eleven classical rules (R1-R11).
  calc_set_rules_is_the_missing_rule(t.set_rule_id) AS is_the_missing_rule      -- True only for Rule 12, the rule naive set theory never wrote down.
FROM set_rules t;

-- ----------------------------------------------------------------------------
-- vw_sets: The universe of sets under discussion. Each set is identified by a slug and defined by a membership condition.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_sets CASCADE;
CREATE VIEW vw_sets WITH (security_invoker = ON) AS
SELECT
  t.set_id,                                                                     -- Stored identity slug, e.g. 'russell-set'.
  t.label,                                                                      -- Human notation for the set, e.g. '{a}', 'R', '∅'.
  t.condition_expression,                                                       -- The membership condition (the predicate / definition) phi defining the set.
  t.is_self_referential,                                                        -- Whether the condition refers to the set's own membership.
  calc_sets_name(t.set_id) AS name,                                             -- Display alias.
  calc_sets_is_russell_set(t.set_id) AS is_russell_set,                         -- Flags the Russell set R = { x | x not-in x }.
  calc_sets_count_of_memberships(t.set_id) AS count_of_memberships,             -- Number of recorded membership facts where this set is the container.
  calc_sets_count_of_null_memberships(t.set_id) AS count_of_null_memberships,   -- Membership facts on this set that are ungrounded (NULL).
  t.memberships                                                                 -- Membership facts for which this set is the container.
FROM sets t;

-- ----------------------------------------------------------------------------
-- vw_membership_facts: The core relation: each fact is a question 'Element in Container' carrying its three-valued answer.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_membership_facts CASCADE;
CREATE VIEW vw_membership_facts WITH (security_invoker = ON) AS
SELECT
  t.membership_fact_id,                                                         -- Stored identity, e.g. 'russell-set-in-russell-set'.
  t.element,                                                                    -- The candidate member (itself a set).
  t.container,                                                                  -- The set being asked about.
  t.membership_value,                                                           -- The three-valued answer to Element in Container.
  calc_membership_facts_name(t.membership_fact_id) AS name,                     -- Readable fact, e.g. 'russell-set ∈ russell-set'.
  calc_membership_facts_container_label(t.membership_fact_id) AS container_label,-- Notation of the container set.
  calc_membership_facts_membership_value_symbol(t.membership_fact_id) AS membership_value_symbol,-- Symbol (T/F/N) of the answer.
  calc_membership_facts_is_bivalent(t.membership_fact_id) AS is_bivalent,       -- Whether the answer is one of the classical values (not NULL).
  calc_membership_facts_is_null(t.membership_fact_id) AS is_null,               -- True when the fact is ungrounded (NULL).
  calc_membership_facts_is_grounded(t.membership_fact_id) AS is_grounded,       -- True when the fact settles to True or False.
  calc_membership_facts_count_of_evaluation_steps(t.membership_fact_id) AS count_of_evaluation_steps,-- Number of evaluation trials recorded for this fact.
  t.evaluation_steps                                                            -- The fixed-point evaluation trials for this fact.
FROM membership_facts t;

-- ----------------------------------------------------------------------------
-- vw_evaluation_steps: Strong Kleene fixed-point evaluation of the Russell fact: each trial value fed through phi = not(R in R). Only NULL is stable, dissolving the Russell paradox into a single ungrounded fixed point.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_evaluation_steps CASCADE;
CREATE VIEW vw_evaluation_steps WITH (security_invoker = ON) AS
SELECT
  t.evaluation_step_id,                                                         -- Stored identity of the trial.
  t.membership_fact,                                                            -- The fact being evaluated.
  t.step_order,                                                                 -- Trial order (1,2,3).
  t.trial_value,                                                                -- The truth value assumed for R in R before applying phi.
  t.resulting_value,                                                            -- The value phi = not(R in R) yields under that assumption.
  calc_evaluation_steps_name(t.evaluation_step_id) AS name,                     -- Readable trial.
  calc_evaluation_steps_is_stable(t.evaluation_step_id) AS is_stable,           -- True when the trial reproduces itself (a fixed point).
  calc_evaluation_steps_outcome(t.evaluation_step_id) AS outcome                -- 'stable fixed point' or 'contradiction'.
FROM evaluation_steps t;



